function initialise(
    bool _isValidatorWithdrawalVault,
    uint8 _poolId,
    uint256 _id,
    address _staderConfig
) external {
    if (isInitialized) {
        revert AlreadyInitialized();
    }
    UtilLib.checkNonZeroAddress(_staderConfig);
    isValidatorWithdrawalVault = _isValidatorWithdrawalVault;
    isInitialized = true;
    poolId = _poolId;
    id = _id;
    staderConfig = IStaderConfig(_staderConfig);
    owner = staderConfig.getAdmin();
}

fallback(bytes calldata _input) external payable returns (bytes memory) {
    address vaultImplementation = isValidatorWithdrawalVault ? staderConfig.getValidatorWithdrawalVaultImplementation() : staderConfig.getNodeELRewardVaultImplementation();
    (bool success, bytes memory data) = vaultImplementation.delegatecall(_input);
    if (!success) {
        revert(string(data));
    }
    return data;
}

function updateStaderConfig(address _staderConfig) external override onlyOwner {
    UtilLib.checkNonZeroAddress(_staderConfig);
    staderConfig = IStaderConfig(_staderConfig);
    emit UpdatedStaderConfig(_staderConfig);
}
